import { writeFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'

import { readManifests, repository } from './manifests.mjs'

export async function syncCompose(directory = repository) {
  const files = readManifests(directory).flatMap((manifest) =>
    manifest.compose ? [manifest.compose] : [],
  )

  await writeFile(
    new URL('compose.app.yml', directory),
    '# Generated by pnpm compose:sync. Do not edit.\n' +
      (files.length
        ? `include:\n${files.map((file) => `  - ${JSON.stringify(file)}\n`).join('')}`
        : 'include: []\n'),
  )

  console.log(
    `Compose: ${files.length} module/connector service file(s): ${files.join(', ') || 'core only'}`,
  )

  return files
}

if (process.argv[1] === fileURLToPath(import.meta.url)) await syncCompose()
